from collections import Counter
import json
def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    for dr,dc in ((1,1),(1,-1)):
        starts=[(r,0) for r in range(h)]+[(0,c) for c in range(1,w)]
        if dc==-1: starts=[(r,w-1) for r in range(h)]+[(0,c) for c in range(w-1)]
        for sr,sc in starts:
            line=[]; r,c=sr,sc
            while 0<=r<h and 0<=c<w: line.append((r,c)); r+=dr; c+=dc
            k=0
            while k<len(line):
                k2=k
                while k2<len(line) and g[line[k2][0]][line[k2][1]]==g[line[k][0]][line[k][1]]: k2+=1
                col=g[line[k][0]][line[k][1]]
                if k2-k>=2 and col!=bg:
                    for r,c in line[:k]:
                        if g[r][c]==bg: out[r][c]=col
                        else: break
                    for r,c in line[k2:]:
                        if g[r][c]==bg: out[r][c]=col
                        else: break
                k=k2
    return out
