lib='''from collections import Counter

def background(grid):
    """The most common cell color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def diagonal_lines(grid, dr, dc):
    """All maximal straight diagonal lines of cells, as lists of (r, c), for step (dr, dc)."""
    h, w = len(grid), len(grid[0])
    if dc == 1:
        starts = [(r, 0) for r in range(h)] + [(0, c) for c in range(1, w)]
    else:
        starts = [(r, w - 1) for r in range(h)] + [(0, c) for c in range(w - 1)]
    for sr, sc in starts:
        line, r, c = [], sr, sc
        while 0 <= r < h and 0 <= c < w:
            line.append((r, c)); r += dr; c += dc
        if line: yield line

def diagonal_segments(grid, min_len=1):
    """All maximal same-color diagonal segments of length >= min_len as (cells, color), over both diagonal directions."""
    bg = background(grid)
    for dr, dc in ((1, 1), (1, -1)):
        for line in diagonal_lines(grid, dr, dc):
            k = 0
            while k < len(line):
                k2 = k
                while k2 < len(line) and grid[line[k2][0]][line[k2][1]] == grid[line[k][0]][line[k][1]]:
                    k2 += 1
                if k2 - k >= min_len and grid[line[k][0]][line[k][1]] != bg:
                    yield line[k:k2], grid[line[k][0]][line[k][1]]
                k = k2

def extend_diagonals(grid, min_len=2):
    """Each diagonal segment of one non-background color (length >= min_len) grows through background cells along its diagonal until blocked by a non-background cell or the border."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = background(grid)
    for cells, col in diagonal_segments(grid, min_len):
        cellset = set(cells)
        r0, c0 = cells[0]; r1, c1 = cells[-1]
        dr, dc = r1 - r0, c1 - c0
        n = max(abs(dr), abs(dc))
        dr, dc = dr // n, dc // n
        for sign in (1, -1):
            r, c = (r1 + dr * sign, c1 + dc * sign) if sign == 1 else (r0 - dr, c0 - dc)
            while 0 <= r < h and 0 <= c < w and grid[r][c] == bg:
                out[r][c] = col; r += dr * sign; c += dc * sign
    return out
